import { EventEmitter } from 'node:events';

export type JSONValue = string | number | boolean | null | JSONValue[] | { [key: string]: JSONValue };
export type MessageMetadata = { [key: string]: JSONValue };

/**
 * One tappable choice offered by a keyboard: label is shown to the user,
 * value is what the bot receives when it is chosen.
 */
export interface CardDetail {
  label: string;
  value: string;
}
export interface Action {
  label: string;
  value: string;
  role?: 'approve' | 'reject';
}
export type CardAction = Action;

export interface FormField {
  key: string;
  label: string;
  type: 'text' | 'multiline' | 'select' | 'multiselect' | 'date' | 'datetime';
  required?: boolean;
  placeholder?: string;
  maxLength?: number;
  options?: KeyboardOption[];
}
export type CardTaskStatus = 'queued' | 'running' | 'waiting' | 'completed' | 'failed' | 'cancelled';

export interface CardTask {
  url?: string;
  id: string;
  title: string;
  status: CardTaskStatus;
}
export interface AgentCard {
  parentID?: string;
  url?: string;
  tasks?: CardTask[];
  sourceID?: string;
  planID?: string;
  kind: 'approval' | 'form' | 'plan' | 'artifact';
  title: string;
  summary: string;
  details?: CardDetail[];
  actions?: CardAction[];
  fields?: FormField[];
  expiresTS?: string;
  status?: string;
  revision?: number;
  progress?: number;
  result?: string;
  answerID?: string;
}
export interface CardUpdate {
  tasks?: CardTask[];
  revision: number;
  status: 'running' | 'waiting' | 'completed' | 'failed' | 'cancelled';
  progress?: number;
  result?: string;
}
export type CardMessage = Message;

export interface MessageInput {
  stream?: boolean;
  content?: string;
  subject?: string;
  metadata?: MessageMetadata | null;
  actions?: Action[];
  card?: AgentCard;
  keyboard?: Keyboard;
  attachments?: string[];
  silent?: boolean;
  ts?: string;
}
export interface MessageUpdate {
  content?: string;
  subject?: string;
  metadata?: MessageMetadata | null;
  actions?: Action[];
  keyboard?: Keyboard;
  card?: CardUpdate;
}

export interface KeyboardOption {
  label: string;
  value: string;
}

/**
 * A set of one-tap answer options attached to a message. The server stamps
 * selected once the user answers; clients render an answered keyboard
 * unclickable.
 */
export interface Keyboard {
  options: KeyboardOption[];
  selected?: string;
}

/** Optional article metadata generated by the server. */
export interface LinkPreview {
  url: string;
  siteName: string;
  title: string;
  description?: string;
  image?: { id: string; width: number; height: number };
}

/** A single chat message, as returned by the API. */
export interface MessageStream {
  status: 'active' | 'completed' | 'failed';
  sequence: number;
  updatedTS: string;
}

export interface StreamInput {
  content: string;
  sequence: number;
  status?: 'active' | 'completed' | 'failed';
}

export interface Message {
  stream?: MessageStream;
  reactions?: Record<string, string>;
  reactionRevision?: number;
  card?: AgentCard;
  fields?: Record<string, string | string[]>;
  cancel?: boolean;
  command?: string;
  argument?: string;
  id: string;
  sessionID: string;
  authorID: string;
  content: string;
  subject?: string;
  metadata?: MessageMetadata | null;
  linkPreview?: LinkPreview;
  previewTS?: string;
  /** Present on bot messages sent with one-tap answer options. */
  keyboard?: Keyboard;
  /** On a keyboard answer: id of the keyboard message. */
  replyTo?: string;
  /** On a keyboard answer: machine value of the chosen option. */
  value?: string;
  silent: boolean;
  read: boolean;
  delivered: boolean;
  /** ISO 8601 timestamp set by the author. */
  authorTS: string;
  /** ISO 8601 timestamp set by the server. */
  createTS: string;
  /** ISO 8601 timestamp of the last edit by the author bot. */
  editTS?: string;
}

/** One entry of the bot's per-session settings schema; values are strings. */
export interface SettingField {
  /** Matches ^[a-z0-9_]{1,32}$. */
  key: string;
  label: string;
  description?: string;
  /** toggle: "true"/"false"; select: one of options; text: ≤256 chars; time: "HH:MM". */
  type: 'toggle' | 'select' | 'text' | 'time';
  options?: KeyboardOption[];
  default?: string;
}

/** The effective settings of a session after a change. */
export interface CollectionField {
  key: string;
  label: string;
  description?: string;
  placeholder?: string;
  maxItems: number;
}

export interface CollectionItem {
  id: string;
  label: string;
  description?: string;
}

/** Compare revision and increment atomically on mutation; reject expired requests. */
export interface CollectionRequest {
  id: string;
  sessionID: string;
  key: string;
  action: 'list' | 'add' | 'remove';
  value?: string;
  itemID?: string;
  revision?: number;
  expiresTS: string;
}

export interface CollectionResult {
  items: CollectionItem[];
  revision: number;
  error?: string;
  changed?: boolean;
}

export interface SessionSettings {
  sessionID: string;
  settings: Record<string, string>;
}

/** A server-side fan-out job created by broadcast(). */
export interface Broadcast {
  id: string;
  content: string;
  subject?: string;
  metadata?: MessageMetadata | null;
  silent: boolean;
  total: number;
  sent: number;
  failed: number;
  done: boolean;
  createTS: string;
  doneTS?: string;
}

/** A bot command shown to users. */
export interface CommandInput {
  type: 'text';
  label?: string;
  placeholder?: string;
  required?: boolean;
  maxLength?: number;
}

export interface Command {
  input?: CommandInput;
  name: string;
  value: string;
  description: string;
}

/** The account on the other side of a session, as visible to the bot. */
export interface SessionUser {
  id: string;
  name?: string;
  /** IANA zone reported by the user's client. */
  timezone?: string;
  /** BCP 47 tag reported by the user's client. */
  locale?: string;
}

/** A conversation between one account and the bot. */
export interface Session {
  id: string;
  unreadCount: number;
  lastMessage?: Message;
  user?: SessionUser;
  /** Effective values of the bot's settings schema, defaults filled in. */
  settings?: Record<string, string>;
  /** A muted session receives messages but no push notifications. */
  muted: boolean;
  /** ISO 8601 timestamp. */
  createTS: string;
}

export interface BotOptions {
  /** Bot client id (shown once on bot creation). */
  clientId: string;
  /** Bot client secret (shown once on bot creation). */
  clientSecret: string;
}

export interface SendOptions {
  stream?: boolean;
  /** Optional plain-text subject, up to 256 characters. */
  subject?: string;
  metadata?: MessageMetadata | null;
  /** Suppress the push notification for the recipient. Default false. */
  silent?: boolean;
}

export interface BotEvents {
  /** Incoming message that is not a registered command. */
  message: [message: Message];
  /** Incoming message whose content (or keyboard answer value) matches a registered command value. */
  command: [message: Message];
  /** A user opened a new session with the bot. */
  new_session: [session: Session];
  /** A session's settings changed (by the user or the bot). */
  settings: [settings: SessionSettings];
  collection_request: [request: CollectionRequest];
  /** Non-fatal background failure (re-grant, reconnect, back-fill, read confirmation). */
  error: [error: Error];
}

/**
 * A BotComm bot: an authenticated client streaming /updates over SSE.
 *
 * The SDK re-grants the access token before expiry, reconnects the stream
 * with a 5s delay, and back-fills unread messages on every (re)connect so
 * nothing is lost while the bot was offline.
 */
export class Bot extends EventEmitter<BotEvents> {
  constructor(options: BotOptions);

  clientId: string;
  clientSecret: string;
  /** Bot ID, resolved from the access token subject on run; null before. */
  id: string | null;

  /**
   * Authorizes the bot, opens the /updates stream and starts listening.
   * Rejects if the initial grant or connect fails; after that the SDK keeps
   * the token fresh and reconnects on its own.
   */
  run(): Promise<void>;

  /** Closes the stream, stops all timers and prevents reconnects. */
  stop(): void;

  /** Posts a message into a session and returns it. */
  startStream(sessionId: string): Promise<Message>;
  updateStream(sessionId: string, messageId: string, input: StreamInput): Promise<Message>;
  react(sessionId: string, messageId: string, emoji?: string): Promise<Message>;
  send(sessionId: string, content: string, options?: SendOptions): Promise<Message>;

  /**
   * Posts a message with one-tap answer options. The user's tap arrives as a
   * 'message' event whose content is the chosen option's label, with replyTo
   * set to the keyboard message's id and value to the option's value (a value
   * matching a registered command emits 'command' instead).
   */
  sendKeyboard(sessionId: string, content: string, options: KeyboardOption[], messageOptions?: SendOptions): Promise<Message>;

  /** Shows a typing indicator to the user for ~5s; repeat every 3-4s while working. */
  typing(sessionId: string): Promise<void>;

  /**
   * Edits a message the bot authored and returns it. Rejects with 409 when
   * the message's keyboard was already answered.
   */
  edit(
    sessionId: string,
    messageId: string,
    changes: { content?: string; subject?: string; metadata?: MessageMetadata | null; keyboard?: Pick<Keyboard, 'options'> },
  ): Promise<Message>;

  /** Deletes a message the bot authored. */
  delete(sessionId: string, messageId: string): Promise<void>;

  /** Sends one message to every session of the bot as a server-side job. */
  broadcast(content: string, options?: SendOptions & { keyboard?: Pick<Keyboard, 'options'> }): Promise<Broadcast>;

  /** Progress of a broadcast job. */
  broadcastStatus(id: string): Promise<Broadcast>;

  /** Publishes the per-session settings schema (≤20 fields); changes emit 'settings'. */
  registerSettings(settings: SettingField[]): Promise<void>;
  sendMessage(sessionId: string, message: MessageInput): Promise<Message>;
  updateMessage(sessionId: string, messageId: string, change: MessageUpdate): Promise<Message>;
  getMessage(sessionId: string, messageId: string): Promise<Message>;
  sendCard(sessionId: string, card: AgentCard): Promise<CardMessage>;
  updateCard(sessionId: string, messageId: string, change: CardUpdate): Promise<CardMessage>;
  getCardMessage(sessionId: string, messageId: string): Promise<CardMessage>;
  registerCollections(collections: CollectionField[]): Promise<void>;
  respondCollection(request: CollectionRequest, result: CollectionResult): Promise<void>;

  /** Sets settings values of a session on behalf of the user. */
  setSettings(sessionId: string, values: Record<string, string>): Promise<SessionSettings>;

  /** Configure before run to publish definitions before recovering messages. */
  argumentCommands: boolean;
  startupCommands: Command[] | null;
  inputMode: 'messages' | 'commands' | 'none' | null;
  /** Configure user input after successfully publishing commands. */
  setInputMode(inputMode: 'messages' | 'commands' | 'none'): Promise<void>;
  /** Controls whether apps show the bot's connection status. */
  setOnlineStatusVisible(visible: boolean): Promise<void>;
  /** Publishes commands; exact routing stays the default. */
  registerCommands(commands: Command[]): Promise<void>;

  /** Fetches all sessions of the bot. */
  sessions(): Promise<Session[]>;
}

export default Bot;
